/**
 ******************************************************************************
 * @file    test_bq34z100.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   Unit tests for the BQ34Z100 fuel-gauge driver.
 *
 * Owner: Brendon Bone (PD5b).
 *
 * Coverage: every public function in bq34z100.h. The scripted bus mock
 * verifies each wrapper addresses the RIGHT command code with the RIGHT
 * byte count, that multi-byte values are assembled little-endian, that
 * signed registers keep their two's-complement meaning, that the multi-step
 * Control()/data-flash sequences run in the exact documented order (with
 * the required settle delays), and that every failure path — NULL pointers,
 * missing bus operations, NACKs at any step — returns BQ_ERROR without
 * further bus traffic.
 ******************************************************************************
 */
#include "unity.h"
#include "bq34z100.h"
#include "mock_bq_bus.h"

#include <string.h>

void setUp(void)
{
    MockBus_Reset();
}

void tearDown(void)
{
}

/* Assert the scripted expectations were consumed exactly, in order. */
#define ASSERT_BUS_CLEAN()                                            \
    do {                                                              \
        TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Mismatches());           \
        TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unconsumed());           \
        TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unexpected());           \
    } while (0)

