/* One test per wrapper: correct command code, 2-byte little-endian read. */
#define DEFINE_U16_TEST(name, fn, cmd)                                \
    static void name(void)                                            \
    {                                                                 \
        uint16_t out = 0U;                                            \
        const uint8_t reply[2] = {0x34U, 0x12U};                      \
        MockBus_ExpectRead((cmd), reply, 2U, 0);                      \
        TEST_ASSERT_EQUAL(BQ_OK, fn(MockBus_Iface(), &out));          \
        TEST_ASSERT_EQUAL_HEX16(0x1234U, out);                        \
        ASSERT_BUS_CLEAN();                                           \
    }

