static void test_init_succeeds_first_probe(void)
{
    const int ready[] = {0};

    MockBus_QueueReady(ready, 1U);
    TEST_ASSERT_EQUAL(BQ_OK, BQ34Z100_Init(MockBus_Iface()));
    TEST_ASSERT_EQUAL_UINT32(1U, MockBus_ReadyCalls());
}

static void test_init_succeeds_on_third_probe(void)
{
    const int ready[] = {-1, -1, 0};

    MockBus_QueueReady(ready, 3U);
    TEST_ASSERT_EQUAL(BQ_OK, BQ34Z100_Init(MockBus_Iface()));
    TEST_ASSERT_EQUAL_UINT32(3U, MockBus_ReadyCalls());
}

static void test_init_fails_after_three_probes(void)
{
    const int ready[] = {-1, -1, -1};

    MockBus_QueueReady(ready, 3U);
    TEST_ASSERT_EQUAL(BQ_ERROR, BQ34Z100_Init(MockBus_Iface()));
    TEST_ASSERT_EQUAL_UINT32(3U, MockBus_ReadyCalls());
}

static void test_init_rejects_null_bus(void)
{
    BQ_Bus no_probe;

    TEST_ASSERT_EQUAL(BQ_ERROR, BQ34Z100_Init(NULL));

    memset(&no_probe, 0, sizeof(no_probe));
    TEST_ASSERT_EQUAL(BQ_ERROR, BQ34Z100_Init(&no_probe));
}

