/* Parameter validation and failure propagation                                */
/* -------------------------------------------------------------------------- */

static void test_read_rejects_null_output(void)
{
    /* No expectations queued: any bus traffic would count as unexpected. */
    TEST_ASSERT_EQUAL(BQ_ERROR, BQ34Z100_ReadVoltage_mV(MockBus_Iface(), NULL));
    TEST_ASSERT_EQUAL(BQ_ERROR, BQ34Z100_ReadSOC_pct(MockBus_Iface(), NULL));
    TEST_ASSERT_EQUAL(BQ_ERROR,
                      BQ34Z100_ReadAverageCurrent_mA(MockBus_Iface(), NULL));
    TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unexpected());
}

static void test_read_rejects_missing_bus_ops(void)
{
    BQ_Bus bad;
    uint16_t out = 0U;

    memset(&bad, 0, sizeof(bad));   /* no mem_read/mem_write at all */
    TEST_ASSERT_EQUAL(BQ_ERROR, BQ34Z100_ReadVoltage_mV(&bad, &out));
    TEST_ASSERT_EQUAL(BQ_ERROR, BQ34Z100_ReadVoltage_mV(NULL, &out));
    TEST_ASSERT_EQUAL(BQ_ERROR, BQ34Z100_ControlCommand(&bad, 0x0000U));
}

static void test_read_failure_propagates(void)
{
    uint16_t out = 0U;

    MockBus_ExpectRead(BQ34Z100_CMD_VOLTAGE, NULL, 2U, -1);
    TEST_ASSERT_EQUAL(BQ_ERROR, BQ34Z100_ReadVoltage_mV(MockBus_Iface(), &out));
    ASSERT_BUS_CLEAN();
}

