/* ControlRead sequencing                                                      */
/* -------------------------------------------------------------------------- */

static void test_control_read_write_fail_stops_sequence(void)
{
    uint16_t out = 0U;
    const uint8_t wr[2] = {0x01U, 0x00U};

    MockBus_ExpectWrite(BQ34Z100_CMD_CONTROL, wr, 2U, -1);
    TEST_ASSERT_EQUAL(BQ_ERROR,
                      BQ34Z100_ReadDeviceType(MockBus_Iface(), &out));
    /* Failed subcommand write means: no settle delay, no read-back. */
    TEST_ASSERT_EQUAL_UINT32(0U, MockBus_DelayCalls());
    ASSERT_BUS_CLEAN();
}

static void test_control_read_applies_settle_delay(void)
{
    uint16_t out = 0U;
    const uint8_t wr[2] = {0x00U, 0x00U};
    const uint8_t rd[2] = {0x00U, 0x00U};

    MockBus_ExpectWrite(BQ34Z100_CMD_CONTROL, wr, 2U, 0);
    MockBus_ExpectRead(BQ34Z100_CMD_CONTROL, rd, 2U, 0);
    TEST_ASSERT_EQUAL(BQ_OK,
                      BQ34Z100_ReadControlStatus(MockBus_Iface(), &out));
    TEST_ASSERT_EQUAL_UINT32(1U, MockBus_DelayCalls());
    TEST_ASSERT_EQUAL_UINT32(2U, MockBus_DelayTotalMs());
    ASSERT_BUS_CLEAN();
}

static void test_control_read_works_without_delay_fn(void)
{
    uint16_t out = 0U;
    const uint8_t wr[2] = {0x08U, 0x00U};
    const uint8_t rd[2] = {0x51U, 0x04U};

    MockBus_ExpectWrite(BQ34Z100_CMD_CONTROL, wr, 2U, 0);
    MockBus_ExpectRead(BQ34Z100_CMD_CONTROL, rd, 2U, 0);
    TEST_ASSERT_EQUAL(BQ_OK,
                      BQ34Z100_ReadChemID(MockBus_IfaceNoDelay(), &out));
    TEST_ASSERT_EQUAL_HEX16(0x0451U, out);
    TEST_ASSERT_EQUAL_UINT32(0U, MockBus_DelayCalls());
    ASSERT_BUS_CLEAN();
}

