static void test_update_status_runs_full_select_sequence(void)
{
    uint8_t out = 0U;
    const uint8_t zero[1]  = {0x00U};
    const uint8_t klass[1] = {82U};
    const uint8_t block[1] = {0U};
    const uint8_t reply[1] = {BQ34Z100_UPDATE_STATUS_QMAX_RA_UPDATED};

    MockBus_ExpectWrite(BQ34Z100_CMD_BLOCK_DATA_CONTROL, zero, 1U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_DATA_FLASH_CLASS, klass, 1U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_DATA_FLASH_BLOCK, block, 1U, 0);
    MockBus_ExpectRead(0x44U, reply, 1U, 0);   /* 0x40 + offset 4 */

    TEST_ASSERT_EQUAL(BQ_OK,
                      BQ34Z100_ReadUpdateStatus(MockBus_Iface(), &out));
    TEST_ASSERT_EQUAL_HEX8(0x06U, out);
    ASSERT_BUS_CLEAN();
}

static void test_update_status_aborts_on_select_failure(void)
{
    uint8_t out = 0U;
    const uint8_t zero[1]  = {0x00U};
    const uint8_t klass[1] = {82U};

    MockBus_ExpectWrite(BQ34Z100_CMD_BLOCK_DATA_CONTROL, zero, 1U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_DATA_FLASH_CLASS, klass, 1U, -1);

    TEST_ASSERT_EQUAL(BQ_ERROR,
                      BQ34Z100_ReadUpdateStatus(MockBus_Iface(), &out));
    ASSERT_BUS_CLEAN();   /* nothing after the failing step */
}

