static void test_df_block_read_sequence_and_data(void)
{
    uint8_t out[32];
    uint8_t blockdata[32];
    const uint8_t zero[1]  = {0x00U};
    const uint8_t klass[1] = {48U};
    const uint8_t block[1] = {1U};
    int i;

    for (i = 0; i < 32; i++) {
        blockdata[i] = (uint8_t)(0xA0 + i);
    }

    MockBus_ExpectWrite(BQ34Z100_CMD_BLOCK_DATA_CONTROL, zero, 1U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_DATA_FLASH_CLASS, klass, 1U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_DATA_FLASH_BLOCK, block, 1U, 0);
    MockBus_ExpectRead(BQ34Z100_CMD_BLOCK_DATA_START, blockdata, 32U, 0);

    TEST_ASSERT_EQUAL(BQ_OK,
                      BQ34Z100_ReadDataFlashBlock(MockBus_Iface(), 48U, 1U, out));
    TEST_ASSERT_EQUAL_UINT8_ARRAY(blockdata, out, 32U);
    ASSERT_BUS_CLEAN();
}

static void test_df_block_read_rejects_null_buffer(void)
{
    TEST_ASSERT_EQUAL(BQ_ERROR,
                      BQ34Z100_ReadDataFlashBlock(MockBus_Iface(), 48U, 0U, NULL));
    TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unexpected());
}

/* -------------------------------------------------------------------------- */
/* Data flash: 16-bit write (the full 9-step commit sequence)                  */
/* -------------------------------------------------------------------------- */

static void queue_df_write_sequence(uint8_t subclass, uint8_t offset,
                                    uint16_t value)
{
    const uint8_t key1[2]  = {0x14U, 0x04U};
    const uint8_t key2[2]  = {0x72U, 0x36U};
    const uint8_t zero[1]  = {0x00U};
    const uint8_t klass[1] = {subclass};
    const uint8_t block[1] = {(uint8_t)(offset / 32U)};
    uint8_t blockdata[32];
    uint8_t patched[2];
    uint8_t checksum_buf[1];
    uint16_t sum = 0U;
    int i;

    for (i = 0; i < 32; i++) {
        blockdata[i] = (uint8_t)i;   /* pre-existing block contents */
    }

    /* 1) unseal */
    MockBus_ExpectWrite(BQ34Z100_CMD_CONTROL, key1, 2U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_CONTROL, key2, 2U, 0);
    /* 2..4) selects */
    MockBus_ExpectWrite(BQ34Z100_CMD_BLOCK_DATA_CONTROL, zero, 1U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_DATA_FLASH_CLASS, klass, 1U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_DATA_FLASH_BLOCK, block, 1U, 0);
    /* 5) read existing block */
    MockBus_ExpectRead(BQ34Z100_CMD_BLOCK_DATA_START, blockdata, 32U, 0);
    /* 6..7) big-endian patch written back at 0x40 + offset%32 */
    patched[0] = (uint8_t)((value >> 8) & 0xFFU);
    patched[1] = (uint8_t)(value & 0xFFU);
    MockBus_ExpectWrite((uint8_t)(BQ34Z100_CMD_BLOCK_DATA_START + (offset % 32U)),
                        patched, 2U, 0);
    /* 8..9) checksum over the patched block, committed to 0x60 */
    for (i = 0; i < 32; i++) {
        uint8_t b = blockdata[i];
        if (i == (int)(offset % 32U))      { b = patched[0]; }
        if (i == (int)(offset % 32U) + 1)  { b = patched[1]; }
        sum = (uint16_t)(sum + b);
    }
    checksum_buf[0] = (uint8_t)(0xFFU - (uint8_t)(sum & 0xFFU));
    MockBus_ExpectWrite(BQ34Z100_CMD_BLOCK_DATA_CHECKSUM, checksum_buf, 1U, 0);
}

static void test_df_write_full_sequence_and_checksum(void)
{
    queue_df_write_sequence(48U, 21U, 3400U);

    TEST_ASSERT_EQUAL(BQ_OK,
                      BQ34Z100_WriteDataFlashU16(MockBus_Iface(),
                                                 48U, 21U, 3400U));
    /* Delays: 2+2 (unseal) + 2+2+2 (selects) + 2 (patch) + 150 (commit). */
    TEST_ASSERT_EQUAL_UINT32(7U, MockBus_DelayCalls());
    TEST_ASSERT_EQUAL_UINT32(162U, MockBus_DelayTotalMs());
    ASSERT_BUS_CLEAN();
}

static void test_df_write_design_capacity_targets_subclass48_offset21(void)
{
    queue_df_write_sequence(48U, 21U, 3400U);

    TEST_ASSERT_EQUAL(BQ_OK,
                      BQ34Z100_WriteDesignCapacity_mAh(MockBus_Iface(), 3400U));
    ASSERT_BUS_CLEAN();
}

static void test_df_write_rejects_offset_straddling_block_end(void)
{
    /* offset%32 == 31 would put the second byte in the next block. */
    TEST_ASSERT_EQUAL(BQ_ERROR,
                      BQ34Z100_WriteDataFlashU16(MockBus_Iface(), 48U, 31U, 1U));
    TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unexpected());   /* no bus traffic */
}

static void test_df_write_aborts_on_block_read_failure(void)
{
    const uint8_t key1[2]  = {0x14U, 0x04U};
    const uint8_t key2[2]  = {0x72U, 0x36U};
    const uint8_t zero[1]  = {0x00U};
    const uint8_t klass[1] = {48U};
    const uint8_t block[1] = {0U};

    MockBus_ExpectWrite(BQ34Z100_CMD_CONTROL, key1, 2U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_CONTROL, key2, 2U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_BLOCK_DATA_CONTROL, zero, 1U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_DATA_FLASH_CLASS, klass, 1U, 0);
    MockBus_ExpectWrite(BQ34Z100_CMD_DATA_FLASH_BLOCK, block, 1U, 0);
    MockBus_ExpectRead(BQ34Z100_CMD_BLOCK_DATA_START, NULL, 32U, -1);

    TEST_ASSERT_EQUAL(BQ_ERROR,
                      BQ34Z100_WriteDataFlashU16(MockBus_Iface(), 48U, 21U, 1U));
    ASSERT_BUS_CLEAN();   /* no patch/checksum traffic after the failure */
}

